#include <iostream>
#include <vector>
#include <algorithm>

using namespace std;

typedef long long ll;

int N, M, K;
vector<ll> A;
vector<ll> dp_val;
vector<ll> dp_cnt;
vector<int> q;

pair<ll, ll> check(ll C) {
    dp_val.assign(N + 2, 0);
    dp_cnt.assign(N + 2, 0);
    q.assign(N + 2, 0);
    int head = 0, tail = 0;
    
    q[tail++] = 0;
    
    for (int i = 1; i <= N; ++i) {
        while (head < tail && q[head] < i - M - 1) {
            head++;
        }
        
        int best_idx = q[head];
        dp_val[i] = dp_val[best_idx] + A[i] - C;
        dp_cnt[i] = dp_cnt[best_idx] + 1;
        
        while (head < tail) {
            int last = q[tail - 1];
            if (dp_val[last] < dp_val[i] || (dp_val[last] == dp_val[i] && dp_cnt[last] <= dp_cnt[i])) {
                tail--;
            } else {
                break;
            }
        }
        q[tail++] = i;
    }
    
    int i = N + 1;
    while (head < tail && q[head] < i - M - 1) {
        head++;
    }
    int best_idx = q[head];
    dp_val[i] = dp_val[best_idx];
    dp_cnt[i] = dp_cnt[best_idx];
    
    return {dp_val[i], dp_cnt[i]};
}

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);
    
    if (!(cin >> N >> M >> K)) return 0;
    A.resize(N + 1);
    for (int i = 1; i <= N; ++i) {
        cin >> A[i];
    }
    
    if (N > (ll)K * (M + 1) + M) {
        cout << -1 << "\n";
        return 0;
    }
    
    auto res0 = check(0);
    if (res0.second < K) {
        cout << res0.first << "\n";
        return 0;
    }

    ll L = -2e9 - 1, R = 2e9 + 1;
    ll ans = -1e18;
    while (L <= R) {
        ll mid = L + (R - L) / 2;
        auto res = check(mid);
        if (res.second >= K) {
            ans = res.first + mid * K;
            L = mid + 1;
        } else {
            R = mid - 1;
        }
    }
    
    cout << ans << "\n";
    
    return 0;
}
